import { useState } from "react";

const API = "http://localhost:8000";

export default function Login() {
  const [tab, setTab] = useState("login"); // "login" | "forgot"
  const [forgotStep, setForgotStep] = useState(1); // 1 = enter email, 2 = enter new password

  const [loginEmail, setLoginEmail] = useState("");
  const [loginPass, setLoginPass] = useState("");
  const [loginError, setLoginError] = useState("");
  const [loginLoading, setLoginLoading] = useState(false);

  const [fpEmail, setFpEmail] = useState("");
  const [fpLoading, setFpLoading] = useState(false);
  const [fpError, setFpError] = useState("");
  const [fpToken, setFpToken] = useState("");

  const [rpPass, setRpPass] = useState("");
  const [rpConfirm, setRpConfirm] = useState("");
  const [rpLoading, setRpLoading] = useState(false);
  const [rpError, setRpError] = useState("");
  const [rpSuccess, setRpSuccess] = useState(false);

  async function handleLogin() {
    setLoginError("");
    setLoginLoading(true);
    try {
      const r = await fetch(`${API}/api/auth/login`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email: loginEmail, password: loginPass }),
      });
      const data = await r.json();
      if (!r.ok) throw new Error(data.message || "Login failed");
      localStorage.setItem("token", data.data.token);
      window.location.href = "/dashboard";
    } catch (e) {
      setLoginError(e.message);
    } finally {
      setLoginLoading(false);
    }
  }

  async function handleSendToken() {
    setFpError("");
    if (!fpEmail) { setFpError("Enter your email address"); return; }
    setFpLoading(true);
    try {
      const r = await fetch(`${API}/api/auth/forgot-password`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email: fpEmail }),
      });
      const data = await r.json();
      if (!r.ok) throw new Error(data.message || "Email not found");
      setFpToken(data.data.resetToken);
      setForgotStep(2);
    } catch (e) {
      setFpError(e.message);
    } finally {
      setFpLoading(false);
    }
  }

  async function handleResetPassword() {
    setRpError("");
    if (!rpPass) { setRpError("Enter a new password"); return; }
    if (rpPass !== rpConfirm) { setRpError("Passwords don't match"); return; }
    setRpLoading(true);
    try {
      const r = await fetch(`${API}/api/auth/reset-password`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ token: fpToken, newPassword: rpPass }),
      });
      const data = await r.json();
      if (!r.ok) throw new Error(data.message || "Reset failed");
      setRpSuccess(true);
    } catch (e) {
      setRpError(e.message);
    } finally {
      setRpLoading(false);
    }
  }

  function goBackToLogin() {
    setTab("login");
    setForgotStep(1);
    setFpEmail("");
    setFpToken("");
    setFpError("");
    setRpPass("");
    setRpConfirm("");
    setRpError("");
    setRpSuccess(false);
  }

  return (
    <div style={{
      minHeight: "100vh",
      background: "#0d0f14",
      display: "flex",
      alignItems: "center",
      justifyContent: "center",
      fontFamily: "'DM Sans', sans-serif",
      padding: "24px",
    }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600&family=Syne:wght@700&display=swap');

        .card {
          background: #161a23;
          border: 1px solid rgba(255,255,255,0.07);
          border-radius: 20px;
          padding: 40px;
          width: 100%;
          max-width: 420px;
          box-shadow: 0 32px 80px rgba(0,0,0,0.6);
        }

        .logo-badge {
          display: inline-flex;
          align-items: center;
          gap: 8px;
          background: rgba(234,126,52,0.12);
          border: 1px solid rgba(234,126,52,0.25);
          border-radius: 8px;
          padding: 6px 12px;
          margin-bottom: 20px;
        }
        .logo-dot { width: 8px; height: 8px; border-radius: 50%; background: #ea7e34; }
        .logo-text { font-family: 'Syne', sans-serif; font-size: 13px; color: #ea7e34; letter-spacing: 0.08em; }

        .heading { font-family: 'Syne', sans-serif; font-size: 26px; color: #f0f0f0; margin: 0 0 4px; font-weight: 700; }
        .subheading { font-size: 14px; color: #5a6070; margin: 0 0 32px; }

        .field-label {
          display: block;
          font-size: 12px;
          font-weight: 500;
          color: #8090a0;
          margin-bottom: 6px;
          letter-spacing: 0.04em;
          text-transform: uppercase;
        }
        .field-input {
          width: 100%;
          box-sizing: border-box;
          background: #1e2330;
          border: 1px solid rgba(255,255,255,0.07);
          border-radius: 10px;
          padding: 12px 14px;
          font-size: 14px;
          color: #e8eaf0;
          outline: none;
          transition: border-color 0.15s;
          font-family: 'DM Sans', sans-serif;
          margin-bottom: 16px;
        }
        .field-input:focus { border-color: rgba(234,126,52,0.5); }
        .field-input::placeholder { color: #3a4255; }

        .btn-primary {
          width: 100%;
          padding: 13px;
          background: #ea7e34;
          color: #fff;
          border: none;
          border-radius: 10px;
          font-size: 15px;
          font-weight: 600;
          cursor: pointer;
          font-family: 'DM Sans', sans-serif;
          transition: opacity 0.15s, transform 0.1s;
          letter-spacing: 0.01em;
        }
        .btn-primary:hover:not(:disabled) { opacity: 0.88; }
        .btn-primary:active:not(:disabled) { transform: scale(0.99); }
        .btn-primary:disabled { opacity: 0.5; cursor: not-allowed; }

        .btn-ghost {
          background: none;
          border: none;
          color: #ea7e34;
          font-size: 13px;
          cursor: pointer;
          font-family: 'DM Sans', sans-serif;
          padding: 0;
          margin-top: 16px;
          display: block;
          width: 100%;
          text-align: center;
          transition: opacity 0.15s;
        }
        .btn-ghost:hover { opacity: 0.7; }

        .error-box {
          background: rgba(220,60,60,0.1);
          border: 1px solid rgba(220,60,60,0.25);
          border-radius: 8px;
          padding: 10px 14px;
          font-size: 13px;
          color: #f07070;
          margin-bottom: 16px;
        }
        .success-box {
          background: rgba(60,190,120,0.1);
          border: 1px solid rgba(60,190,120,0.25);
          border-radius: 8px;
          padding: 10px 14px;
          font-size: 13px;
          color: #60c890;
          margin-bottom: 16px;
          text-align: center;
        }

        .step-indicator {
          display: flex;
          align-items: center;
          gap: 8px;
          margin-bottom: 24px;
        }
        .step-dot {
          width: 24px; height: 24px; border-radius: 50%;
          display: flex; align-items: center; justify-content: center;
          font-size: 11px; font-weight: 600;
        }
        .step-dot.active { background: #ea7e34; color: #fff; }
        .step-dot.done { background: rgba(60,190,120,0.2); color: #60c890; border: 1px solid rgba(60,190,120,0.3); }
        .step-dot.inactive { background: rgba(255,255,255,0.05); color: #3a4255; }
        .step-line { flex: 1; height: 1px; background: rgba(255,255,255,0.07); }
        .step-label { font-size: 11px; color: #5a6070; margin-top: 2px; }

        .back-link {
          display: flex;
          align-items: center;
          gap: 6px;
          font-size: 12px;
          color: #5a6070;
          cursor: pointer;
          margin-bottom: 24px;
          width: fit-content;
          transition: color 0.15s;
          background: none;
          border: none;
          font-family: 'DM Sans', sans-serif;
          padding: 0;
        }
        .back-link:hover { color: #9aa0b0; }

        .divider {
          display: flex; align-items: center; gap: 12px;
          margin: 20px 0;
        }
        .divider-line { flex: 1; height: 1px; background: rgba(255,255,255,0.06); }
        .divider-text { font-size: 11px; color: #3a4255; }
      `}</style>

      <div className="card">
        <div className="logo-badge">
          <div className="logo-dot" />
          <span className="logo-text">Q3 ADMIN</span>
        </div>

        {/* ── LOGIN TAB ── */}
        {tab === "login" && (
          <>
            <h1 className="heading">Sign in</h1>
            <p className="subheading">Access your admin portal</p>

            {loginError && <div className="error-box">{loginError}</div>}

            <label className="field-label">Email</label>
            <input
              className="field-input"
              type="email"
              placeholder="admin@q3.com"
              value={loginEmail}
              onChange={e => setLoginEmail(e.target.value)}
              onKeyDown={e => e.key === "Enter" && handleLogin()}
            />

            <label className="field-label">Password</label>
            <input
              className="field-input"
              type="password"
              placeholder="••••••••"
              value={loginPass}
              onChange={e => setLoginPass(e.target.value)}
              onKeyDown={e => e.key === "Enter" && handleLogin()}
            />

            <button
              className="btn-primary"
              onClick={handleLogin}
              disabled={loginLoading}
              style={{ marginBottom: 0 }}
            >
              {loginLoading ? "Signing in…" : "Sign in"}
            </button>

            <button className="btn-ghost" onClick={() => setTab("forgot")}>
              Forgot your password?
            </button>
          </>
        )}

        {/* ── FORGOT PASSWORD TAB ── */}
        {tab === "forgot" && (
          <>
            <button className="back-link" onClick={goBackToLogin}>
              ← Back to sign in
            </button>

            <h1 className="heading">Reset password</h1>
            <p className="subheading">
              {forgotStep === 1
                ? "We'll send a reset link to your email"
                : "Choose a new password for your account"}
            </p>

            {/* Step indicator */}
            <div className="step-indicator">
              <div>
                <div className={`step-dot ${forgotStep === 1 ? "active" : "done"}`}>
                  {forgotStep > 1 ? "✓" : "1"}
                </div>
              </div>
              <div className="step-line" />
              <div>
                <div className={`step-dot ${forgotStep === 2 ? "active" : "inactive"}`}>2</div>
              </div>
            </div>

            {/* STEP 1 — enter email */}
            {forgotStep === 1 && (
              <>
                {fpError && <div className="error-box">{fpError}</div>}
                <label className="field-label">Email address</label>
                <input
                  className="field-input"
                  type="email"
                  placeholder="admin@q3.com"
                  value={fpEmail}
                  onChange={e => setFpEmail(e.target.value)}
                  onKeyDown={e => e.key === "Enter" && handleSendToken()}
                />
                <button
                  className="btn-primary"
                  onClick={handleSendToken}
                  disabled={fpLoading}
                >
                  {fpLoading ? "Sending…" : "Continue"}
                </button>
              </>
            )}

            {/* STEP 2 — new password (token is auto-filled from step 1, hidden from user) */}
            {forgotStep === 2 && (
              <>
                {rpSuccess ? (
                  <>
                    <div className="success-box">
                      ✓ Password updated successfully
                    </div>
                    <button className="btn-primary" onClick={goBackToLogin}>
                      Back to sign in
                    </button>
                  </>
                ) : (
                  <>
                    {rpError && <div className="error-box">{rpError}</div>}
                    <div style={{
                      background: "rgba(60,190,120,0.06)",
                      border: "1px solid rgba(60,190,120,0.15)",
                      borderRadius: "8px",
                      padding: "10px 14px",
                      fontSize: "13px",
                      color: "#5a7060",
                      marginBottom: "20px",
                    }}>
                      ✓ Verified — <span style={{ color: "#8090a0" }}>{fpEmail}</span>
                    </div>
                    <label className="field-label">New password</label>
                    <input
                      className="field-input"
                      type="password"
                      placeholder="Min. 8 characters"
                      value={rpPass}
                      onChange={e => setRpPass(e.target.value)}
                    />
                    <label className="field-label">Confirm password</label>
                    <input
                      className="field-input"
                      type="password"
                      placeholder="Repeat new password"
                      value={rpConfirm}
                      onChange={e => setRpConfirm(e.target.value)}
                      onKeyDown={e => e.key === "Enter" && handleResetPassword()}
                    />
                    <button
                      className="btn-primary"
                      onClick={handleResetPassword}
                      disabled={rpLoading}
                    >
                      {rpLoading ? "Updating…" : "Set new password"}
                    </button>
                    <button
                      className="btn-ghost"
                      onClick={() => { setForgotStep(1); setFpToken(""); setRpError(""); }}
                    >
                      Use a different email
                    </button>
                  </>
                )}
              </>
            )}
          </>
        )}
      </div>
    </div>
  );
}
